use serde::{Deserialize, Serialize};
use std::collections::HashMap;

pub fn compute_locs (matcher : & [TokenTree]) -> Vec < MatcherLoc > { fn inner (tts : & [TokenTree] , locs : & mut Vec < MatcherLoc > , next_metavar : & mut usize , seq_depth : usize ,) { for tt in tts { match tt { TokenTree :: Token (token) => { locs . push (MatcherLoc :: Token { token : * token }) ; } TokenTree :: Delimited (span , _ , delimited) => { let open_token = Token :: new (delimited . delim . as_open_token_kind () , span . open) ; let close_token = Token :: new (delimited . delim . as_close_token_kind () , span . close) ; locs . push (MatcherLoc :: Delimited) ; locs . push (MatcherLoc :: Token { token : open_token }) ; inner (& delimited . tts , locs , next_metavar , seq_depth) ; locs . push (MatcherLoc :: Token { token : close_token }) ; } TokenTree :: Sequence (_ , seq) => { let dummy = MatcherLoc :: Eof ; locs . push (dummy) ; let next_metavar_orig = * next_metavar ; let op = seq . kleene . op ; let idx_first = locs . len () ; let idx_seq = idx_first - 1 ; inner (& seq . tts , locs , next_metavar , seq_depth + 1) ; if let Some (separator) = & seq . separator { locs . push (MatcherLoc :: SequenceSep { separator : separator . clone () }) ; locs . push (MatcherLoc :: SequenceKleeneOpAfterSep { idx_first }) ; } else { locs . push (MatcherLoc :: SequenceKleeneOpNoSep { op , idx_first }) ; } locs [idx_seq] = MatcherLoc :: Sequence { op , num_metavar_decls : seq . num_captures , idx_first_after : locs . len () , next_metavar : next_metavar_orig , seq_depth , } ; } & TokenTree :: MetaVarDecl { span , name : bind , kind } => { locs . push (MatcherLoc :: MetaVarDecl { span , bind , kind , next_metavar : * next_metavar , seq_depth , }) ; * next_metavar += 1 ; } TokenTree :: MetaVar (..) | TokenTree :: MetaVarExpr (..) => unreachable ! () , } } } let mut locs = vec ! [] ; let mut next_metavar = 0 ; inner (matcher , & mut locs , & mut next_metavar , 0) ; locs . push (MatcherLoc :: Eof) ; locs }